      out.write("  <script>\r\n");
      out.write("    function validateCardholderName() {\r\n");
      out.write("      const name = document.getElementById(\"cardName\").value.trim();\r\n");
      out.write("      const regex = /^[A-Za-z\\s]{2,}$/;\r\n");
      out.write("      const valid = regex.test(name);\r\n");
      out.write("      document.getElementById(\"nameError\").style.display = valid ? \"none\" : \"block\";\r\n");
      out.write("      return valid;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    function validateCardNumber() {\r\n");
      out.write("      const number = document.getElementById(\"cardNumber\").value.replace(/\\s+/g, \"\");\r\n");
      out.write("      const regex = /^\\d{16}$/;\r\n");
      out.write("      const valid = regex.test(number);\r\n");
      out.write("      document.getElementById(\"numberError\").style.display = valid ? \"none\" : \"block\";\r\n");
      out.write("      return valid;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    function validateExpiry() {\r\n");
      out.write("      const expiry = document.getElementById(\"expiry\").value.trim();\r\n");
      out.write("      const regex = /^(0[1-9]|1[0-2])\\/\\d{2}$/;\r\n");
      out.write("      const [month, year] = expiry.split(\"/\").map(Number);\r\n");
      out.write("      const now = new Date();\r\n");
      out.write("      const currentMonth = now.getMonth() + 1;\r\n");
      out.write("      const currentYear = now.getFullYear() % 100;\r\n");
      out.write("\r\n");
      out.write("      const valid = regex.test(expiry) && (year > currentYear || (year === currentYear && month >= currentMonth));\r\n");
      out.write("      document.getElementById(\"expiryError\").style.display = valid ? \"none\" : \"block\";\r\n");
      out.write("      return valid;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    function validateCVV() {\r\n");
      out.write("      const cvv = document.getElementById(\"cvv\").value.trim();\r\n");
      out.write("      const regex = /^\\d{3,4}$/;\r\n");
      out.write("      const valid = regex.test(cvv);\r\n");
      out.write("      document.getElementById(\"cvvError\").style.display = valid ? \"none\" : \"block\";\r\n");
      out.write("      return valid;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    function validateFormFields() {\r\n");
      out.write("      const nameValid = validateCardholderName();\r\n");
      out.write("      const numberValid = validateCardNumber();\r\n");
      out.write("      const expiryValid = validateExpiry();\r\n");
      out.write("      const cvvValid = validateCVV();\r\n");
      out.write("      return nameValid && numberValid && expiryValid && cvvValid;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    function handleSubmit(event) {\r\n");
